patch:
diff --git a/src/server.js b/src/server.js
index 0969320..8b4ab25 100644
--- a/src/server.js
+++ b/src/server.js
@@ -22,9 +22,25 @@ export function createApp(inventory = Inventory.fromFile()) {
   })

   router.post('/cart/quote', ({ body }) => {
+    // Basic validation for client errors
+    if (!body || !Array.isArray(body.items) || body.items.length === 0) {
+      return { status: 400, body: { error: 'items is required and must be a non-empty array' } }
+    }
     const cart = new Cart(inventory)
-    for (const item of body.items) cart.addItem(item.id, item.quantity)
-    if (body.discountCode) cart.applyDiscount(body.discountCode)
+    for (const item of body.items) {
+      if (!item || typeof item.id !== 'string') return { status: 400, body: { error: 'each item must have an id string' } }
+      if (!Number.isInteger(item.quantity) || item.quantity <= 0) return { status: 400, body: { error: 'quantity must be a positive integer' } }
+      const book = inventory.find(item.id)
+      if (!book) return { status: 400, body: { error: `Unknown book: ${item.id}` } }
+      cart.addItem(item.id, item.quantity)
+    }
+    if (body.discountCode) {
+      try {
+        cart.applyDiscount(body.discountCode)
+      } catch (err) {
+        return { status: 400, body: { error: err.message } }
+      }
+    }
     const total = cart.total()
     return { status: 200, body: { totalCents: total, total: formatCurrency(total) } }
   })
